# John and Ann sign up for Codewars
def john_ann(n):
    john, ann = [0], [1]
    for i in range(1, n):
        john.append(i - ann[john[i - 1]])
        ann.append(i - john[ann[i - 1]])
    return john, ann

def john(n):
    return john_ann(n)[0]

def ann(n):
    return john_ann(n)[1]

def sum_john(n):
    return sum(john(n))

def sum_ann(n):
    return sum(ann(n))

# 459. Repeated Substring Pattern
class Solution:
    def repeatedSubstringPattern(self, s: str) -> bool:
        # Solution 1
        return s in s[1:] + s[:-1]
        # Solution 2
        l = len(s)
        j = l
        for i in range(l // 2):
            while len(s[:i+1] * j) >= l:
                j -= 1
            if s[:i+1] * (j+1) == s:
                return True
        return False
        # Solution 3
        def kmp_table(W):
            n = len(W)
            T = [0 for _ in range(n)]
            T[0] = -1
            pos = 0
            for i in range(1, n):
                if W[i] == W[pos]:
                    T[i] = T[pos]
                else:
                    T[i] = pos
                    pos = T[pos]
                    while pos >= 0 and W[i] != W[pos]:
                        pos = T[pos]
                pos += 1
            return T
        string, substring = s[1:] + s[:-1], s
        m = len(substring)
        n = len(string)
        T = kmp_table(substring)
        pos = 0
        i = 0
        while i < n:
            if string[i] != substring[pos]:
                pos = T[pos]
                if pos < 0:
                    pos += 1
                    i += 1
            else:
                i += 1
                pos += 1
                if pos == m:
                    return True
        return False

# Elementary Arithmetic - Carries Count
def solve(input_string):
    l, count, out, flag = input_string.split('\n'), 0, [], False
    for i in l:
        a, b = i.split()
        for j in range(len(a)-1, -1, -1):
            s = int(a[j]) + int(b[j])
            if flag:
                s += 1
                flag = False
            if s > 9:
                flag = True
                count += 1
        out.append(f"{count} carry operations" if count else "No carry operation")
        count, flag = 0, False
    return '\n'.join(out)

