        if len(s) != len(goal):
            return False
        if s == goal and len(set(s)) < len(s):
            return True
        count = []
        for i in range(len(s)):
            if s[i] != goal[i]:
                count.append([s[i], goal[i]])
        if len(count) == 2 and count[0] == count[-1][::-1]:
            return True
        return False
    
