#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def minDepth(self, root: Optional[TreeNode]) -> int:
        if root is None:
            return 0
        l = self.minDepth(root.left)
        r = self.minDepth(root.right)
        if root.left is None:
            return 1 + r
        if root.right is None:
            return 1 + l
        return min(l, r) + 1

