# Missing number in Unordered Arithmetic Progression
def find(seq):
    mi, ma, result = seq[0], seq[0], seq[0]
    for i in range(1, len(seq)):
        mi, ma, result = min(mi, seq[i]), max(ma, seq[i]), result ^ seq[i]
    if mi == ma:
        return mi
    differens = (ma - mi) // len(seq)
    while mi <= ma:
        result = result ^ mi
        mi += differens
    return result
