# The area between the vertex of the parabola and x-axis
def area(a, b, c):
    d = b**2 - 4 * a * c
    if d <= 0:
        return 0
    # calculate x1 and x2
    x1, x2 = (-b + d**.5) / (2 * a), (-b - d**.5) / (2 * a)
    # calculate integral by formula: ∫[a, b] f(x) dx >= ∫(((a/3)(x)^3 + (b/2)(x)^2 + c*(x)))dx
    return abs(((a/3) * (x1)**3 + (b/2) * (x1)**2 + c * (x1)) - ((a/3) * (x2)**3 + (b/2) * (x2)**2 + c * (x2)))

# 34. Find First and Last Position of Element in Sorted Array
class Solution:
    def searchRange(self, nums: List[int], target: int) -> List[int]:
        if len(nums) == 0:
            return [-1, -1]
        pos, left, right = [-1, -1], 0, len(nums) - 1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == target:
                pos[0], right = mid, mid - 1
            if nums[mid] < target:
                left = mid + 1
            if nums[mid] > target:
                right = mid - 1
        if pos[0] == -1:
            return pos
        left, right = 0, len(nums) - 1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == target:
                pos[1], left = mid, mid + 1
            if nums[mid] < target:
                left = mid + 1
            if nums[mid] > target:
                right = mid - 1
        return pos

