# My solution with flag
class Solution:
    def search(self, nums: List[int], target: int) -> int:
        left, right, flag = 0, len(nums) - 1, True
        while left <= right:
            mid = (left + right) // 2
            flag = nums[left] <= nums[mid]
            if flag:
                if nums[left] <= target <= nums[mid]:
                    if nums[mid] == target:
                        return mid
                    if nums[mid] > target:
                        right = mid - 1
                    else:
                        left = mid + 1
                else:
                    left = mid + 1
            else:
                if nums[mid] <= target <= nums[right]:
                    if nums[mid] == target:
                        return mid
                    if nums[mid] > target:
                        right = mid - 1
                    else:
                        left = mid + 1
                else:
                    right = mid - 1
        return -1

# Classic binary search
class Solution:
    def search(self, nums: List[int], target: int) -> int:
        left, right = 0, len(nums) - 1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == target:
                return mid
            if nums[mid] < nums[right]:
                if nums[mid] < target <= nums[right]:
                    left = mid + 1
                else:
                    right = mid - 1
            else:
                if nums[left] <= target < nums[mid]:
                    right = mid - 1
                else:
                    left = mid + 1
        return -1

# Diagonals sum
def sum_diagonals(matrix):
    if not matrix[0]:
        return 0
    total, step = 0, 0
    for i in matrix:
        total += i[step] + i[-step + -1]
        step += 1
    return total

