# 139. Word Break
class Solution:
    def wordBreak(self, s: str, wordDict: List[str]) -> bool:
        l = [False] * (len(s) + 1)
        l[0] = True
        for i in range(1, len(s) + 1):
            for j in range(i):
                if l[j] and s[j:i] in wordDict:
                    l[i] = True
                    break
        return l[-1]

# ASCII Shift Encryption/Decryption
def ascii_encrypt(plaintext):
    if not plaintext:
        return plaintext
    return ''.join(chr(ord(plaintext[i]) + i) for i in range(len(plaintext)))


def ascii_decrypt(encrypted):
    if not encrypted:
        return encrypted
    return ''.join(chr(ord(encrypted[i]) - i) for i in range(len(encrypted)))

# 2744. Find Maximum Number of String Pairs
class Solution:
    def maximumNumberOfStringPairs(self, words: List[str]) -> int:
        count = 0
        while True:
            top = 0
            for i in range(len(words)):
                for j in range(i + 1, len(words)):
                    if words[i][::-1] == words[j]:
                        count += 1
                        top += 1
                        words.pop(j)
                        words.pop(i)
                        break
            if top == 0:
                break
        return count
    
# Race Ceremony
from math import ceil
def race_podium(b):
    x = ceil((b) / 3) + 1
    y = min(x - 1, b - x - 1)
    return y, x, b - x - y

# 2595. Number of Even and Odd Bits
class Solution:
    def evenOddBit(self, n: int) -> List[int]:
        odd, even, flag = 0, 0, True
        for i in bin(n)[2:][::-1]:
            if flag:
                flag = False
                if i == '1':
                    even += 1
            else:
                flag = True
                if i == '1':
                    odd += 1
        return [even, odd]

# Point in Polygon
def point_in_polygon(poly, point) -> bool:
    x,y  = point
    n = len(poly)
    inside = False
    p1x,p1y = poly[0]
    for i in range(n+1):
        p2x,p2y = poly[i % n]
        if y > min(p1y,p2y):
            if y <= max(p1y,p2y):
                if x <= max(p1x,p2x):
                    if p1y != p2y:
                        xints = (y-p1y)*(p2x-p1x)/(p2y-p1y)+p1x
                    if p1x == p2x or x <= xints:
                        inside = not inside
        p1x,p1y = p2x,p2y
    return inside

# 74. Search a 2D Matrix
class Solution:
    def searchMatrix(self, matrix: List[List[int]], target: int) -> bool:
        left, right, colum = 0, (len(matrix) * len(matrix[0])) - 1, len(matrix[0])
        while left <= right:
            middle = (left + right) // 2
            if matrix[middle // colum][middle % colum] == target:
                return True
            if matrix[middle // colum][middle % colum] > target:
                right = middle - 1
            else:
                left = middle + 1
        return False
    
