# Range Extraction
def solution(args):
    if len(args) == 1:
        return str(args)
    l = []
    while args:
        cop = [args[0]]
        for i in args[1:]:
            if cop[-1] + 1 == i:
                cop.append(i)
            else:
                break
        if cop[0] != cop[-1]:
            if len(cop) > 2:
                l.append(str(cop[0])+'-'+str(cop[-1]))
            else:
                l.append(str(cop[0]))
                l.append(str(cop[-1]))
        else:
            l.append(str(cop[0]))
        args = args[args.index(cop[-1]) + 1:]
    return ','.join(l)

# Roman Numerals Encoder
def solution(n):
    integer = ''
    rom = [(1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'), (100, 'C'), (90, 'XC'),
           (50, 'L'), (40, 'XL'), (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')]
    while n > 0:
        for k,v in rom:
            while n >= k:
                integer += v
                n -= k
    return integer

# 1221. Split a String in Balanced Strings
# Solution 1 by Stack
class Solution(object):
    def balancedStringSplit(self, s):
        stack, count, top = [], 0, s[0]
        for i in range(len(s)):
            if len(stack) == 0:
                count += 1
                top = s[i]
            if s[i] == top:
                stack.append(s[i])
            elif len(stack) != 0:
                stack.pop()
        return count
# Solution 2 by count (best solution)
class Solution(object):
    def balancedStringSplit(self, s):
        top, count = 0, 0
        for i in range(len(s)):
            if s[i] == 'L':
                top += 1
            else:
                top -= 1
            if top == 0:
                count += 1
        return count
# Solution 3 - My initial solution
class Solution(object):
    def balancedStringSplit(self, s):
        count, left, right = 0, 0, 0
        for i in s:
            if i == 'R':
                right += 1
            else:
                left += 1
            if left == right:
                count += 1
                left = 0
                right = 0
        return count

# 646. Maximum Length of Pair Chain
class Solution(object):
    def findLongestChain(self, pairs):
        if len(pairs) == 1:
            return 1
        lenght = 1
        pairs = sorted(pairs, key=lambda x: x[1])
        top = pairs[0][1]
        for i in range(1, len(pairs)):
            if top < pairs[i][0]:
                lenght += 1
                top = pairs[i][1]
        return lenght

