# 2784. Check if Array is Good
# Solution 1
class Solution:
    def isGood(self, nums: List[int]) -> bool:
        m = max(nums)
        if len(nums) != m + 1:
            return False
        nums.sort()
        for i in range(1, m + 1):
            if i != nums[i-1]:
                return False
        return m == nums[-1]
# Solution 2
