import sys

def solution(n: int) -> str:
    height: int = 0
    total: int = 0
    while True:
        cubes_needed: int = (height + 1) * (height + 2) // 2
        if total + cubes_needed > n:
            break
        height += 1
        total += cubes_needed
    return str(height)

