import sys


def solution(n: int) -> str:
    max_seq: int = 0
    cur_seq: int = 0
    prev_num: int = 0
    nums: list = list(map(int, sys.stdin.readline().rstrip().split()))
    for idx in range(n):
        if nums[idx] <= prev_num:
            cur_seq = 1
        else:
            cur_seq += 1
        prev_num = nums[idx]
        max_seq = max(max_seq, cur_seq)
    return str(max_seq)

