# Python O(logN) O(1) Math
import sys


def solution(t: int) -> None:
    for _ in range(t):
        n: int = int(sys.stdin.readline().rstrip())
        output: int = 0
        mod: int = 1
        is_valid: bool = True
        while is_valid:
            for num in range(1, 10):
                if num * mod <= n:
                    output += 1
                else:
                    sys.stdout.write(str(output) + '\n')
                    is_valid = False
                    break
            mod = mod * 10 + 1


