    for _ in range(t):
        n: int = int(sys.stdin.readline().rstrip())
        nums: list[int] = list(map(int, sys.stdin.readline().rstrip().split()))
        sys.stdout.write(str(min_operations_to_good_array(n, nums)) + '\n')


