        x: int = nums[0] & 1
        y: int = nums[1] & 1
        is_valid: bool = True
        for i in range(n):
            if i & 1 and nums[i] & 1 != y:
                is_valid = False
                break
            elif i & 1 == 0 and nums[i] & 1 != x:
                is_valid = False
                break
        sys.stdout.write(['NO', 'YES'][is_valid] + '\n')


