    oranges: list[int] = list(map(int, sys.stdin.readline().rstrip().split()))
    output: int = 0
    total_juice: int = 0
    for orange in oranges:
        if orange > b: continue
        total_juice += orange
        if total_juice > d:
            output += 1
            total_juice = 0
    sys.stdout.write('{}\n'.format(output))


