import sys


def solution() -> None:
    t: int = int(sys.stdin.readline().rstrip())
    for _ in range(t):
        n, m = map(int, sys.stdin.readline().rstrip().split())
        grid: list[str] = []
        for _ in range(n):
            row: str = sys.stdin.readline().rstrip()
            grid.append(row)
        name: str = 'vika'
