import sys


def solution() -> None:
    n: int = int(sys.stdin.readline().rstrip())
    for i in range(1, n + 1):
        base: int = 1
        for j in range(1, i + 1):
            if i % j != 0: continue
            elif base >= j and base % j == 0: continue
            else: base *= j
        sys.stdout.write('{} '.format(base))
    sys.stdout.write('\n')


