#
# # SELECT * FROM numbers ORDER BY value DESC
# query().select().from_(numbers).order_by(descendent_compare).execute()
# # [9, 8, 7, 6, 5, 4, 3, 2, 1]
# from() supports multiple collections:
#
# teachers = [
#   {
#     "teacher_id": "1",
#     "teacher_name": "Peter"
